ClassicEditor.create(document.getElementById("activity"),{toolbar:{items:["heading","|","fontFamily","fontSize","bold","italic","alignment","removeFormat","|","bulletedList","numberedList","|","indent","outdent","|","insertTable","fontBackgroundColor","fontColor","undo","redo","imageInsert","link","mediaEmbed","codeBlock","blockQuote","horizontalLine"]},language:"es",image:{toolbar:["imageTextAlternative","imageStyle:full","imageStyle:side"]},table:{contentToolbar:["tableColumn","tableRow","mergeTableCells"]},link:{addTargetToExternalLinks:!0,defaultProtocol:"http://"},mediaEmbed:{previewsInData:!0},licenseKey:""}).then(function(e){window.editor=e;var t=document.getElementById("activity");t&&t.form&&t.form.addEventListener("submit",function(){var o=e.getData();if(o)try{t.value=btoa(encodeURIComponent(o).replace(/%([0-9A-F]{2})/g,function(e,t){return String.fromCharCode("0x"+t)}))}catch(e){t.value=o}})}).catch(function(e){console.error(e)});